<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAuth } from './stores/auth'
import { api,errorText,onSessionExpired,sessionEpoch } from './api'
import { roles } from './domain'
import type { Row } from './domain'
import UserWatermark from './components/UserWatermark.vue'
import ThemeToggle from './components/ThemeToggle.vue'
import CommandPalette from './components/CommandPalette.vue'
import { LayoutDashboard,ListTodo,Inbox,Handshake,Bell,ChartNoAxesCombined,Target,ShieldCheck,UsersRound,CalendarDays,Building2,BriefcaseBusiness,Users,Tags,ListFilter,Send,ScrollText,PanelLeftClose,PanelLeftOpen } from 'lucide-vue-next'
import { createTotpQr } from './totp-qr'
const sourceUrl=import.meta.env.VITE_SOURCE_URL||'https://github.com/DreamyXiam/task-workbench'
const auth=useAuth(),route=useRoute(),router=useRouter(),boot=ref(true),busy=ref(false),error=ref(''),account=ref(''),password=ref(''),totp=ref(''),recovery=ref(''),oldPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),setup=ref<Row|null>(null),useRecovery=ref(false),mobileMenu=ref(false),security=ref(false),recoveryCodes=ref<string[]>([]),securityStep=ref('totp')
const nav=computed(()=>{const common=[{to:'/',label:'工作概览',mark:'概'},{to:'/tasks',label:'任务中心',mark:'任'},{to:'/mine',label:'我的任务',mark:'我'},{to:'/collaborations',label:'协同确认',mark:'协'},{to:'/notifications',label:'通知中心',mark:'知'}];if(auth.me?.role!=='EMPLOYEE'&&!auth.me?.delegation)common.push({to:'/reports',label:'统计分析',mark:'统'},{to:'/kpi',label:'部门考核',mark:'绩'});if(['GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role??''))common.push({to:'/admin/audit-logs',label:'操作留痕',mark:'审'});common.push({to:'/organization-changes',label:'岗位与交接',mark:'岗'});if(auth.me?.role!=='EMPLOYEE'&&!auth.me?.delegation)common.push({to:'/calendar-simulation',label:'日历模拟',mark:'历'});return common})
const navIcons:Record<string,unknown>={'/':LayoutDashboard,'/tasks':ListTodo,'/mine':Inbox,'/collaborations':Handshake,'/notifications':Bell,'/reports':ChartNoAxesCombined,'/kpi':Target,'/admin/audit-logs':ShieldCheck,'/organization-changes':UsersRound,'/calendar-simulation':CalendarDays}
const adminIcons:Record<string,unknown>={companies:Building2,departments:BriefcaseBusiness,users:Users,tags:Tags,rules:ListFilter,'notification-channels':Send,'audit-logs':ScrollText}
const adminNav=[['companies','公司管理'],['departments','部门管理'],['users','用户与岗位'],['tags','职能标签'],['rules','匹配规则'],['notification-channels','通知渠道'],['audit-logs','操作日志']]
const commandItems=computed(()=>[...nav.value.map(({to,label})=>({to,label})),...(auth.me?.role==='ADMIN'?adminNav.map(([id,label])=>({to:'/admin/'+id,label})):[])])
function initialSidebarCollapsed(){try{return localStorage.getItem('task-workbench:sidebar')==='collapsed'}catch{return false}}
const sidebarCollapsed=ref(initialSidebarCollapsed())
function toggleSidebar(){sidebarCollapsed.value=!sidebarCollapsed.value;try{localStorage.setItem('task-workbench:sidebar',sidebarCollapsed.value?'collapsed':'expanded')}catch{/* Storage may be unavailable. */}}
const needsSecurity=computed(()=>!!auth.me&&!auth.ready||security.value||recoveryCodes.value.length>0)
const setupQr=computed(()=>createTotpQr(typeof setup.value?.otpauthUri==='string'?setup.value.otpauthUri:''))
onSessionExpired(()=>{if(!auth.me)return;auth.clear();error.value='会话已失效，请重新登录';setup.value=null;security.value=false;recoveryCodes.value=[]})
async function perform(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function login(){if(!account.value.trim()||!password.value){error.value='请输入工号和密码';return}await perform(async()=>{await auth.login({account:account.value.trim(),password:password.value,totp:totp.value||undefined,recoveryCode:recovery.value||undefined});password.value='';totp.value='';recovery.value='';router.replace('/')})}
async function changePassword(){if(newPassword.value.length<12||newPassword.value.length>72||!/[A-Za-z]/.test(newPassword.value)||!/[0-9]/.test(newPassword.value)||newPassword.value!==confirmPassword.value){error.value='新密码须为12至72位并含字母和数字，两次输入需一致';return}await perform(async()=>{const result=await api.post('/auth/change-password',{oldPassword:oldPassword.value,newPassword:newPassword.value});oldPassword.value='';newPassword.value='';confirmPassword.value='';if(result?.reauthenticate){auth.clear();error.value='密码已更新，请使用新密码重新登录'}else{await auth.refresh();ElMessage.success('密码已更新')}})}
async function verify(){await perform(async()=>{const result=await api.post(useRecovery.value?'/auth/totp/recover':setup.value?'/auth/totp/confirm':'/auth/totp/verify',useRecovery.value?{recoveryCode:recovery.value}:{code:totp.value});totp.value='';recovery.value='';setup.value=null;security.value=false;recoveryCodes.value=result?.recoveryCodes??[];await auth.refresh()})}
async function logout(){await perform(async()=>{await auth.logout();setup.value=null;security.value=false;recoveryCodes.value=[];router.replace('/')})}
async function context(scopeId:string){const scopes=auth.me?.scopes??[];if(!scopes.some(s=>s.id===scopeId))return;setup.value=null;security.value=false;await perform(async()=>{await auth.switchContext(scopeId);router.replace('/')})}
async function setupTotp(){await perform(async()=>{setup.value=await api.post('/auth/totp/setup')})}
onMounted(async()=>{try{await auth.refresh()}catch(e){if((e as Row).status!==401)error.value=errorText(e)}finally{boot.value=false}})
onBeforeUnmount(()=>{setup.value=null})
</script>
<template>
<div v-if="boot" class="boot" role="status">正在建立安全会话…</div>
<div v-else-if="!auth.me" class="login-page"><aside class="login-story"><div class="brand"><span class="brand-mark">任</span><span>任务工作台</span></div><div><p class="eyebrow">TASK WORKBENCH · V1.5</p><h1>目标清晰，<br>协同有序，<br>落实有据。</h1><p>从任务布置到成果验收，让组织协同形成闭环。</p><div class="login-flow"><span>布置</span><span>执行</span><span>验收</span><span>复盘</span></div></div><small>内部协同平台 · Asia/Shanghai</small></aside><main class="login-panel"><div class="login-theme"><ThemeToggle/></div><section class="login-form"><p class="eyebrow">安全访问</p><h2>登录工作台</h2><p class="muted">使用组织工号，进入您的工作空间。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="login"><el-form-item label="工号" required><el-input v-model="account" size="large" autocomplete="username" placeholder="请输入工号"/></el-form-item><el-form-item label="密码" required><el-input v-model="password" size="large" type="password" show-password autocomplete="current-password" placeholder="请输入密码"/></el-form-item><el-collapse><el-collapse-item title="动态验证 / 恢复码（按需填写）" name="mfa"><el-form-item label="六位动态验证码"><el-input v-model="totp" maxlength="6" inputmode="numeric" autocomplete="one-time-code"/></el-form-item><el-form-item label="恢复码"><el-input v-model="recovery" type="password" autocomplete="off"/></el-form-item></el-collapse-item></el-collapse><el-button class="login-submit" type="primary" native-type="submit" size="large" :loading="busy">登录工作台</el-button></el-form><p class="login-note">请勿共享账号。浏览器需允许本站会话 Cookie。<br>若内置浏览器无法登录或下载，请在系统浏览器打开。</p></section></main></div>
<div v-else-if="needsSecurity" class="security-page">
<div class="security-card">
<div class="security-theme"><ThemeToggle/></div>
<div class="brand"><span class="brand-mark">安</span><b>账号安全验证</b></div><p class="muted">{{ auth.me.name }} · {{ roles[auth.me.role] }}</p><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div v-if="security&&!auth.me.mustChangePassword&&!recoveryCodes.length" class="status-tabs"><button :class="{selected:securityStep==='totp'}" @click="securityStep='totp'">动态验证</button><button :class="{selected:securityStep==='password'}" @click="securityStep='password';setup=null">修改密码</button></div><el-form v-if="auth.me.mustChangePassword||securityStep==='password'" label-position="top" @submit.prevent="changePassword"><h2>{{ auth.me.mustChangePassword?'首次登录，请更新密码':'更新账号密码' }}</h2><el-form-item label="当前密码"><el-input v-model="oldPassword" type="password" autocomplete="current-password"/></el-form-item><el-form-item label="新密码（12至72位，含字母及数字）"><el-input v-model="newPassword" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="再次输入新密码"><el-input v-model="confirmPassword" type="password" autocomplete="new-password"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">更新密码</el-button></el-form>
<div v-else-if="recoveryCodes.length"><h2>请妥善保存恢复码</h2><p class="muted">恢复码仅显示一次，每个只能使用一次。请离线保管。</p><div class="secret-box"><p v-for="code in recoveryCodes" :key="code"><code>{{ code }}</code></p></div><el-button type="primary" @click="recoveryCodes=[]">我已保存，进入工作台</el-button></div><div v-else><h2>动态验证</h2><p>在验证器应用输入动态验证码，或使用一次性恢复码。</p><el-button v-if="!setup&&!auth.me.totpBound" :loading="busy" @click="setupTotp">首次使用：绑定验证器</el-button><div v-if="setup" class="secret-box"><p>使用验证器应用扫描二维码，或手动输入下方密钥。</p><svg v-if="setupQr" class="totp-qr" :viewBox="`0 0 ${setupQr.size+8} ${setupQr.size+8}`" role="img" aria-label="验证器绑定二维码" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><template v-for="(row,y) in setupQr.modules" :key="y"><rect v-for="(dark,x) in row" :key="x" :x="x+4" :y="y+4" width="1" height="1" :fill="dark?'black':'white'"/></template></svg><code>{{ setup.secret||setup.manualKey }}</code><p v-if="setup.otpauthUri" class="wrap">{{ setup.otpauthUri }}</p><p v-if="setup.recoveryCodes?.length">恢复码：{{ setup.recoveryCodes.join(' / ') }}</p></div><el-form label-position="top" @submit.prevent="verify"><el-form-item :label="useRecovery?'一次性恢复码':'六位动态验证码'"><el-input v-if="useRecovery" v-model="recovery" type="password" autocomplete="off"/><el-input v-else v-model="totp" maxlength="6" inputmode="numeric" autocomplete="one-time-code"/></el-form-item><el-checkbox v-model="useRecovery">使用恢复码</el-checkbox><el-button type="primary" native-type="submit" :loading="busy">验证并继续</el-button></el-form><el-button v-if="security" text @click="security=false;setup=null">返回工作台</el-button></div><el-button text @click="logout">退出登录</el-button>
</div>
</div>
<div v-else class="app-layout" :class="{'sidebar-collapsed':sidebarCollapsed}">
<header class="app-header"><router-link to="/" class="brand"><span class="brand-mark">任</span><b>任务工作台</b><span class="brand-divider"/><small>组织协同</small></router-link><div class="header-right"><CommandPalette :items="commandItems"/><ThemeToggle/><el-dropdown @command="context"><el-button text>{{ roles[auth.me.role] }} <span class="scope-caption">· {{ auth.me.companyId==null?'全局':auth.me.companyId }}</span> ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="s in auth.me.scopes" :key="s.id" :command="s.id">{{ roles[s.role] }} · {{ s.companyId==null?'全局':s.companyId }} {{ s.deptId||'' }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><router-link class="notification-link" to="/notifications" aria-label="打开通知中心">通知</router-link><el-dropdown><button class="profile"><span class="avatar">{{ auth.me.name.slice(-2) }}</span><span class="profile-name">{{ auth.me.name }}</span></button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="security=true;securityStep='totp'">账号安全</el-dropdown-item><el-dropdown-item @click="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
<aside class="sidebar"><div class="sidebar-toolbar"><span class="nav-heading">工作空间</span><button type="button" class="sidebar-toggle" :aria-label="sidebarCollapsed?'展开侧边栏':'收起侧边栏'" :title="sidebarCollapsed?'展开侧边栏':'收起侧边栏'" :aria-expanded="!sidebarCollapsed" @click="toggleSidebar"><PanelLeftOpen v-if="sidebarCollapsed" :size="17" aria-hidden="true"/><PanelLeftClose v-else :size="17" aria-hidden="true"/></button></div><nav aria-label="主导航"><router-link v-for="n in nav" :key="n.to" :to="n.to" :title="sidebarCollapsed?n.label:undefined" :aria-label="n.label" :class="{active:route.path===n.to||(n.to==='/tasks'&&route.path.startsWith('/tasks/'))}"><component :is="navIcons[n.to]" class="nav-icon" :size="17" aria-hidden="true"/><span class="nav-label">{{ n.label }}</span></router-link><template v-if="auth.me.role==='ADMIN'"><p class="nav-heading">系统管理</p><router-link v-for="a in adminNav" :key="a[0]" :to="'/admin/'+a[0]" :title="sidebarCollapsed?a[1]:undefined" :aria-label="a[1]" :class="{active:route.path==='/admin/'+a[0]}"><component :is="adminIcons[a[0]]" class="nav-icon" :size="17" aria-hidden="true"/><span class="nav-label">{{ a[1] }}</span></router-link></template></nav><div class="sidebar-foot"><span class="online-dot"/>组织会话已连接<br><small>内部数据，请按权限使用</small></div></aside>
<main id="main-content" class="main-content"><el-alert v-if="error" :title="error" type="error" closable @close="error=''"/><router-view :key="auth.me.id+':'+auth.me.role+':'+auth.me.companyId+':'+sessionEpoch()"/></main><nav class="mobile-nav" aria-label="移动导航"><router-link to="/">概览</router-link><router-link to="/tasks">任务</router-link><router-link to="/mine">我的</router-link><button @click="mobileMenu=true">更多</button></nav><el-drawer v-model="mobileMenu" title="工作空间" direction="btt" size="70%"><nav class="drawer-nav"><router-link v-for="n in nav" :key="n.to" :to="n.to" @click="mobileMenu=false">{{ n.label }}</router-link><template v-if="auth.me.role==='ADMIN'"><router-link v-for="a in adminNav" :key="a[0]" :to="'/admin/'+a[0]" @click="mobileMenu=false">{{ a[1] }}</router-link></template></nav></el-drawer><UserWatermark :key="auth.me.id+auth.me.role+auth.me.companyId"/>
</div>
<footer class="source-notice"><a :href="sourceUrl" target="_blank" rel="noopener noreferrer">对应源码 · AGPL-3.0</a></footer>
</template>
<style scoped>
.totp-qr{display:block;width:192px;max-width:100%;height:auto;margin:12px auto 16px;background:#fff}
.source-notice{padding:10px 16px;text-align:center;font-size:12px;background:#f5f7fa}
.source-notice a{color:#185fa5;text-decoration:underline;overflow-wrap:anywhere}
@media(max-width:767px){.source-notice{padding-bottom:80px}}
</style>
